</div>
<script>(()=>{
const form=document.getElementById('order-allocation-form'),type=document.getElementById('assignment-type'),vendorWrap=document.getElementById('vendor-select-wrap'),vendor=document.getElementById('assignment-vendor'),hidden=document.getElementById('order-allocation-value'),confirmButton=document.getElementById('confirm-assignment'),editButton=document.getElementById('edit-assignment'),confirmedBox=document.getElementById('confirmed-assignee-box'),confirmedName=document.getElementById('confirmed-assignee-name'),decision=document.getElementById('order-decision-section');
const toast=(message,error=false)=>{const box=document.getElementById('order-toast');if(!box)return;box.className='order-toast '+(error?'error':'success');box.classList.remove('d-none');document.getElementById('order-toast-title').textContent=error?'Unable to save':'Success';document.getElementById('order-toast-message').textContent=message;document.getElementById('order-toast-icon').className=error?'fa-solid fa-circle-exclamation mt-1':'fa-solid fa-circle-check mt-1';clearTimeout(window.__orderToastTimer);window.__orderToastTimer=setTimeout(()=>box.classList.add('d-none'),5000);};
const sync=()=>{const hasVendor=type?.value==='vendor';if(vendorWrap)vendorWrap.hidden=!hasVendor;if(vendor)vendor.required=hasVendor;if(hidden)hidden.value=hasVendor?(vendor?.value||''):'admin';};type?.addEventListener('change',sync);vendor?.addEventListener('change',sync);sync();
const lock=(name)=>{type.disabled=true;if(vendor){vendor.disabled=true}confirmButton.hidden=true;editButton.hidden=false;if(confirmedBox){confirmedBox.hidden=false;confirmedBox.className='allocation-status mb-3';confirmedBox.innerHTML='<span class="review-label d-block mb-2">Confirmed allocation</span><span class="confirmed-assignee"><i class="fa-solid fa-lock"></i><span>'+name.replace(/[<>&]/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;'})[c])+'</span><span class="badge rounded-pill text-bg-primary ms-1">Confirmed</span></span>';}if(decision)decision.hidden=false};
editButton?.addEventListener('click',()=>{type.disabled=false;if(vendor)vendor.disabled=false;confirmButton.hidden=false;editButton.hidden=true;if(decision)decision.hidden=true});
form?.addEventListener('submit',async event=>{event.preventDefault();sync();if(hidden.value===''){toast('Select an active vendor before confirming allocation.',true);return}confirmButton.disabled=true;const original=confirmButton.innerHTML;confirmButton.innerHTML='<span class="spinner-border spinner-border-sm me-1"></span>Saving...';try{const response=await fetch(form.action,{method:'POST',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':form.querySelector('[name=_token]').value},body:new FormData(form),credentials:'same-origin'});const result=await response.json().catch(()=>({message:'The server returned an invalid response.'}));if(!response.ok)throw new Error(result.message||Object.values(result.errors||{})[0]?.[0]||'Allocation could not be saved.');const name=type.value==='admin'?'Admin':(vendor.options[vendor.selectedIndex]?.text||'Vendor');if(result.allocation_type==='vendor'&&result.redirect_url){window.location.href=result.redirect_url;return}lock(name);toast(result.message||'Allocation confirmed successfully.')}catch(error){toast(error.message||'Allocation could not be saved.',true)}finally{confirmButton.disabled=false;confirmButton.innerHTML=original}});
const reason=document.getElementById('rejection-reason');document.getElementById('reject-order-button')?.addEventListener('click',()=>bootstrap.Modal.getOrCreateInstance(document.getElementById('rejectOrderModal')).show());reason?.addEventListener('input',()=>document.getElementById('reason-count').textContent=reason.value.length);
document.getElementById('approve-order-button')?.addEventListener('click',()=>bootstrap.Modal.getOrCreateInstance(document.getElementById('approveOrderModal')).show());
const ajaxDecision=async(formId,successText)=>{const actionForm=document.getElementById(formId);actionForm?.addEventListener('submit',async event=>{event.preventDefault();const button=actionForm.querySelector('button[type=submit]');if(button.disabled)return;if(actionForm.id==='reject-order-form'&&!reason.value.trim()){reason.focus();return}button.disabled=true;const label=button.querySelector('.button-label');if(label)label.innerHTML='<span class="spinner-border spinner-border-sm me-1"></span>Processing...';try{const response=await fetch(actionForm.action,{method:'POST',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':actionForm.querySelector('[name=_token]').value},body:new FormData(actionForm),credentials:'same-origin'});const result=await response.json().catch(()=>({message:'The request could not be completed.'}));if(!response.ok)throw new Error(result.message||Object.values(result.errors||{})[0]?.[0]||'The action could not be completed.');toast(successText);window.setTimeout(()=>window.location.href=result.redirect_url||window.location.href,650)}catch(error){toast(error.message||'The action could not be completed.',true);button.disabled=false}})};ajaxDecision('approve-order-form','Order approved successfully.');ajaxDecision('reject-order-form','Order rejected and the reason recorded.');
})();</script>
